// ─── The app's catalog, as the website uses it ───────────────────────────────
// library.json is generated by scripts/sync-library.mjs from the app's `books`
// table; don't edit it by hand. The covers and hero images live on the app's
// CDN (R2).

import data from "./library.json";

export const levels = ["A1", "A2", "B1", "B2", "C1"] as const;
export type Level = (typeof levels)[number];

export interface LibraryItem {
  id: string;
  // adaptation: a classic rewritten at an easier level (Classic Adaptations)
  // classic: a full-length original · story: a short Owloud story
  kind: "adaptation" | "classic" | "story";
  title: string;
  author: string;
  level: Level;
  chapters: number;
  seconds: number; // all chapters together
  cover: string; // 2:3 (a story's is its hero image)
  hero: string; // 3:2
  summary: { es: string; en: string };
  freeFull: boolean; // every chapter free, not just the first
  order: number | null;
}

export const libraryItems = data as LibraryItem[];

// Only the levels something is written at (A1 has stories but no books)
export const catalogLevels = levels.filter((l) =>
  libraryItems.some((i) => i.level === l),
);

/** The catalog in numbers, for every page that quotes them */
export const catalogStats = {
  books: libraryItems.filter((i) => i.kind !== "story").length,
  stories: libraryItems.filter((i) => i.kind === "story").length,
  hours: Math.round(libraryItems.reduce((s, i) => s + i.seconds, 0) / 3600),
  // Adapted classics that are free from start to finish
  freeAdaptations: libraryItems.filter(
    (i) => i.kind === "adaptation" && i.freeFull,
  ).length,
};

/** One item by its app id. Throws, so a renamed book fails the build. */
export function libraryItem(id: string): LibraryItem {
  const item = libraryItems.find((i) => i.id === id);
  if (!item) throw new Error(`"${id}" is not in library.json`);
  return item;
}
